<script setup lang="ts">
import {onMounted,ref,computed} from 'vue'
import {useRouter} from 'vue-router'
import {purchaseApi} from '@/api/purchases'
import type {PurchaseProduct,Supplier,PurchaseItemInput} from '@/api/purchases'
const router=useRouter(),suppliers=ref<Supplier[]>([]),warehouses=ref<Array<{id:number;name:string}>>([]),catalog=ref<PurchaseProduct[]>([]),search=ref(''),supplierId=ref(''),warehouseId=ref(''),items=ref<Array<PurchaseItemInput&{product_name:string;sku:string;variant_name:string|null}>>([]),discount=ref(0),tax=ref(0),note=ref(''),error=ref(''),saving=ref(false)
const subtotal=computed(()=>items.value.reduce((s,i)=>s+Math.round(Number(i.quantity||0)*i.unit_cost),0)),grand=computed(()=>Math.max(0,subtotal.value-discount.value+tax.value))
const money=(v:number)=>new Intl.NumberFormat('en-BD',{style:'currency',currency:'BDT'}).format(v/100)
async function load(){try{const [s,c]=await Promise.all([purchaseApi.suppliers({is_active:1,per_page:100}),purchaseApi.catalog()]);suppliers.value=s.data.data;catalog.value=c.data.data}catch(e:any){error.value=e?.response?.data?.message||'Could not load purchase data.'}}
async function loadWarehouses(){try{const {default:http}=await import('@/api/http');const r=await http.get('/v1/warehouses',{params:{per_page:100}});warehouses.value=r.data.data||[]}catch{/* If the inventory API response differs, choose a warehouse ID manually below. */}}
function add(p:PurchaseProduct){const found=items.value.find(i=>i.product_variant_id===p.id);if(found)found.quantity=String(Number(found.quantity)+1);else items.value.push({product_variant_id:p.id,quantity:'1',unit_cost:p.purchase_price,product_name:p.product_name,variant_name:p.variant_name,sku:p.sku})}
function remove(id:number){items.value=items.value.filter(i=>i.product_variant_id!==id)}
async function save(){error.value='';saving.value=true;try{const r=await purchaseApi.createPurchase({supplier_id:Number(supplierId.value),warehouse_id:Number(warehouseId.value),items:items.value.map(({product_variant_id,quantity,unit_cost})=>({product_variant_id,quantity,unit_cost})),discount_amount:discount.value,tax_amount:tax.value,note:note.value||undefined});await router.push({name:'purchases.show',params:{id:r.data.data.id}})}catch(e:any){error.value=e?.response?.data?.message||'Could not create purchase.'}finally{saving.value=false}}
onMounted(()=>{load();loadWarehouses()})
</script>
<template><section class="page"><header><div><small>PROCUREMENT / PURCHASE ORDER</small><h1>New purchase</h1><p>Create a draft order. Inventory changes only after receiving it.</p></div><RouterLink :to="{name:'purchases.index'}">Back to purchases</RouterLink></header><p v-if="error" class="error">{{error}}</p><div class="layout"><div class="main card"><div class="two"><label>Supplier<select v-model="supplierId"><option value="">Select supplier</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Receive into warehouse<select v-model="warehouseId"><option value="">Select warehouse</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.name}}</option></select></label></div><h3>Purchase items</h3><input v-model="search" class="search" placeholder="Search products by name or SKU"><div class="catalog"><button v-for="p in catalog.filter(x=>(x.product_name+' '+x.sku).toLowerCase().includes(search.toLowerCase()))" :key="p.id" type="button" @click="add(p)"><b>{{p.product_name}}</b><small>{{p.variant_name||'Default'}} · {{p.sku}}</small><strong>{{money(p.purchase_price)}}</strong></button></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Qty</th><th>Unit cost</th><th>Line total</th><th></th></tr></thead><tbody><tr v-for="i in items" :key="i.product_variant_id"><td><b>{{i.product_name}}</b><small>{{i.sku}}</small></td><td><input v-model="i.quantity" type="number" min=".001" step=".001"></td><td><input v-model.number="i.unit_cost" type="number" min="0"></td><td>{{money(Math.round(Number(i.quantity)*i.unit_cost))}}</td><td><button class="remove" @click="remove(i.product_variant_id)">×</button></td></tr><tr v-if="!items.length"><td colspan="5" class="empty">Choose products from the catalog above.</td></tr></tbody></table></div><label>Notes<textarea v-model="note" rows="3" placeholder="Optional supplier or delivery notes"></textarea></label></div><aside class="card summary"><h3>Purchase summary</h3><div><span>Subtotal</span><b>{{money(subtotal)}}</b></div><label>Discount (minor units)<input v-model.number="discount" type="number" min="0"></label><label>Tax (minor units)<input v-model.number="tax" type="number" min="0"></label><div class="total"><span>Grand total</span><strong>{{money(grand)}}</strong></div><button :disabled="saving||!supplierId||!warehouseId||!items.length" @click="save">{{saving?'Saving...':'Save draft purchase'}}</button><small>Unit costs and totals are revalidated by the server. No stock is added until the purchase is received.</small></aside></div></section></template>
<style scoped>
.page{color:#172033}.page header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.page small{color:#64748b;font-size:10px;letter-spacing:1px;font-weight:800}.page h1{font-size:25px;margin:5px 0}.page p{color:#7b8798;font-size:13px}.page header a{color:#334155;font-size:12px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:16px}.card{background:#fff;border:1px solid #e7ebf1;border-radius:13px;padding:18px}.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}.page label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;margin-bottom:15px}.page input,.page select,.page textarea{padding:10px;border:1px solid #dfe5ed;border-radius:7px;min-width:0}.main h3,.summary h3{font-size:15px}.search{width:100%;box-sizing:border-box;margin-bottom:10px}.catalog{display:flex;gap:8px;overflow:auto;padding-bottom:10px}.catalog button{min-width:150px;text-align:left;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:10px;display:flex;flex-direction:column;gap:5px}.catalog small,.catalog strong{font-size:10px;color:#64748b}.table-wrap{overflow:auto;margin:12px 0}table{width:100%;border-collapse:collapse;white-space:nowrap}td,th{padding:11px;border-top:1px solid #edf0f4;text-align:left;font-size:12px}th{color:#64748b;font-size:10px}td small{display:block;color:#94a3b8}td input{width:90px}.remove{border:0;background:#fee2e2;color:#b91c1c;border-radius:6px}.empty{text-align:center;color:#94a3b8}.summary>div{display:flex;justify-content:space-between;margin:16px 0;font-size:12px}.summary label input{width:100%;box-sizing:border-box}.summary .total{border-top:1px solid #e2e8f0;padding-top:15px;font-size:14px}.summary .total strong{font-size:19px}.summary>button{width:100%;background:#172033;color:white;border:0;border-radius:8px;padding:12px}.summary>small{display:block;color:#94a3b8;font-size:10px;margin-top:12px}.error{color:#be123c}@media(max-width:900px){.layout{grid-template-columns:1fr}.two{grid-template-columns:1fr}}
</style>
